"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { formatTime } from "../lib/date";
import { type ScheduleEvent, type ScheduleResource, groupByStart } from "../lib/schedule";

export interface TimeSlotListProps extends React.HTMLAttributes<HTMLDivElement> {
  events: ScheduleEvent[];
  /** Resources voor kleur, avatar en het label rechts op een kaart. */
  resources?: ScheduleResource[];
  /** Toont de naam van de resource als tag op elke kaart. */
  showResource?: boolean;
  /** Aantal kolommen waarin de kaarten van één tijdslot worden gelegd. */
  minCardWidth?: number;
  emptyLabel?: React.ReactNode;
  onEventClick?: (event: ScheduleEvent) => void;
  /** Eigen inhoud voor een kaart. */
  renderEvent?: (event: ScheduleEvent, resource?: ScheduleResource) => React.ReactNode;
  /** Extra tekst of knoppen rechtsonder op een kaart. */
  renderEventMeta?: (event: ScheduleEvent) => React.ReactNode;
}

/**
 * TimeSlotList — de dag als verticale tijdlijn: per tijdstip één regel, met
 * daarnaast een kaartje voor elke afspraak op dat moment. Leest als een
 * dagoverzicht en werkt goed op smalle schermen.
 */
export const TimeSlotList = React.forwardRef<HTMLDivElement, TimeSlotListProps>(
  function TimeSlotList(
    {
      events,
      resources,
      showResource = true,
      minCardWidth = 230,
      emptyLabel = "Niets gepland",
      onEventClick,
      renderEvent,
      renderEventMeta,
      className,
      ...rest
    },
    ref
  ) {
    const byKey = React.useMemo(() => {
      const map = new Map<string, ScheduleResource>();
      for (const resource of resources ?? []) map.set(resource.key, resource);
      return map;
    }, [resources]);

    const slots = React.useMemo(() => groupByStart(events), [events]);

    if (slots.length === 0) {
      return (
        <div ref={ref} className={cn("lui-slots", className)} {...rest}>
          <div className="lui-slots-empty">{emptyLabel}</div>
        </div>
      );
    }

    return (
      <div ref={ref} className={cn("lui-slots", className)} {...rest}>
        {slots.map((slot) => (
          <div className="lui-slot" key={slot.start}>
            <div className="lui-slot-time">
              <span className="lui-slot-time-label">{formatTime(slot.start)}</span>
            </div>

            <div
              className="lui-slot-cards"
              style={{ gridTemplateColumns: `repeat(auto-fill, minmax(${minCardWidth}px, 1fr))` }}
            >
              {slot.events.map((event) => {
                const resource = byKey.get(event.resource);
                const color = event.color ?? resource?.color;
                const tone = event.tone ?? "accent";

                return (
                  <div
                    key={event.id}
                    role={onEventClick && !event.blocked ? "button" : undefined}
                    tabIndex={onEventClick && !event.blocked ? 0 : undefined}
                    className={cn("lui-slot-card", event.blocked && "lui-slot-card-blocked")}
                    style={color ? ({ ["--lui-event-color" as string]: color } as React.CSSProperties) : undefined}
                    onClick={() => !event.blocked && onEventClick?.(event)}
                    onKeyDown={(keyEvent) => {
                      if (keyEvent.key === "Enter" || keyEvent.key === " ") {
                        keyEvent.preventDefault();
                        if (!event.blocked) onEventClick?.(event);
                      }
                    }}
                  >
                    {renderEvent ? (
                      renderEvent(event, resource)
                    ) : (
                      <>
                        {resource?.media && <span className="lui-slot-media">{resource.media}</span>}
                        <span className="lui-slot-body">
                          <span className="lui-slot-title">{event.title}</span>
                          <span className="lui-slot-meta">
                            {!event.blocked && (
                              <span className={cn("lui-slot-dot", `lui-tone-${tone}`)} aria-hidden="true" />
                            )}
                            {event.subtitle ?? `${event.end - event.start} min`}
                            {renderEventMeta?.(event)}
                          </span>
                        </span>
                        {showResource && resource && (
                          <span
                            className="lui-slot-tag"
                            style={
                              resource.color
                                ? {
                                    background: `color-mix(in srgb, ${resource.color} 14%, transparent)`,
                                    color: resource.color,
                                  }
                                : undefined
                            }
                          >
                            {resource.label}
                          </span>
                        )}
                      </>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    );
  }
);

/* ============================ TimeSlotList ============================ */
.lui-slots { display: flex; flex-direction: column; min-width: 0; }
.lui-slots-empty {
  padding: 40px 16px; text-align: center;
  font-size: 13px; color: var(--text-3); font-style: italic;
}

.lui-slot { display: flex; align-items: flex-start; gap: 14px; padding: 10px 0; }
.lui-slot + .lui-slot { border-top: 1px dashed var(--border); }

.lui-slot-time {
  flex: none; width: 62px; padding-top: 8px;
  display: flex; justify-content: flex-end;
}
.lui-slot-time-label {
  font-size: 13px; font-weight: 700; color: var(--text-2);
  font-variant-numeric: tabular-nums;
}

.lui-slot-cards { flex: 1; min-width: 0; display: grid; gap: 8px; }

.lui-slot-card {
  --lui-event-color: var(--accent);
  display: flex; align-items: center; gap: 10px; min-width: 0;
  padding: 9px 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 3px solid var(--lui-event-color);
  border-radius: var(--r-md);
  transition: border-color var(--dur-fast), box-shadow var(--dur-fast), background var(--dur-fast);
}
.lui-slot-card[role="button"] { cursor: pointer; }
.lui-slot-card[role="button"]:hover { box-shadow: var(--sh-sm); border-color: var(--border-strong); }
.lui-slot-card[role="button"]:focus-visible { outline: none; box-shadow: var(--ring); }

.lui-slot-media { flex: none; display: flex; }
.lui-slot-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.lui-slot-title {
  font-size: 13.5px; font-weight: 650; color: var(--text);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.lui-slot-meta {
  display: flex; align-items: center; gap: 6px;
  font-size: 11.5px; color: var(--text-3);
}
.lui-slot-dot { width: 7px; height: 7px; border-radius: var(--r-full); flex: none; }

.lui-slot-tag {
  flex: none; padding: 3px 9px; border-radius: var(--r-full);
  background: var(--surface-3); color: var(--text-2);
  font-size: 11px; font-weight: 650; white-space: nowrap;
}

.lui-slot-card-blocked {
  --lui-event-color: var(--red);
  background-image: repeating-linear-gradient(
    -45deg,
    var(--red-tint) 0,
    var(--red-tint) 4px,
    var(--surface) 4px,
    var(--surface) 9px
  );
}
.lui-slot-card-blocked .lui-slot-title { color: var(--red); }

@media (max-width: 560px) {
  .lui-slot { gap: 10px; }
  .lui-slot-time { width: 46px; }
}

import type * as React from "react";

/**
 * Gedeeld datamodel voor alle agendaweergaven.
 *
 * WeekSchedule, ResourceColumns, Swimlanes en TimeSlotList werken op precies
 * dezelfde gegevens, zodat je met één knop van weergave kunt wisselen zonder
 * je data om te bouwen.
 */

export type ScheduleTone = "accent" | "green" | "amber" | "red" | "blue" | "violet" | "neutral";

/** Een kolom of rij in de agenda: een dag, een arts, een kamer, een machine. */
export interface ScheduleResource {
  /** Unieke sleutel; events verwijzen hiernaar. */
  key: string;
  label: React.ReactNode;
  /** Tweede regel, bv. het dagnummer of het aantal afspraken. */
  sublabel?: React.ReactNode;
  /** Avatar of icoon links van het label. */
  media?: React.ReactNode;
  /** Eigen kleur voor deze resource (koptekst, tag, blokken zonder eigen kleur). */
  color?: string;
  /** Markeert deze kolom als vandaag. */
  today?: boolean;
  /** Hele kolom gearceerd, bv. een sluitingsdag of afwezigheid. */
  blocked?: boolean;
  blockedLabel?: React.ReactNode;
}

export interface ScheduleEvent {
  id: string;
  /** Sleutel van de resource (dag, arts, kamer …) waar dit item bij hoort. */
  resource: string;
  /** Begin in minuten sinds middernacht (09:30 = 570). */
  start: number;
  /** Einde in minuten sinds middernacht. */
  end: number;
  title: React.ReactNode;
  subtitle?: React.ReactNode;
  tone?: ScheduleTone;
  /** Eigen kleur; overschrijft `tone` en de kleur van de resource. */
  color?: string;
  /** Kan niet versleept of aangepast worden. */
  locked?: boolean;
  /** Geblokkeerde tijd: gearceerd, nooit versleepbaar, geen klikactie. */
  blocked?: boolean;
  /** Vrij veld voor je eigen gegevens. */
  meta?: unknown;
}

/** Positie van een event wanneer overlappende items naast elkaar staan. */
export interface LaidOutEvent<T extends { start: number; end: number }> {
  event: T;
  /** Kolomindex binnen de groep overlappende items. */
  lane: number;
  /** Aantal kolommen in die groep. */
  lanes: number;
}

/**
 * Legt overlappende items naast elkaar: items die elkaar raken vormen een
 * cluster en krijgen daarbinnen elk een eigen kolom.
 */
export function packLanes<T extends { start: number; end: number }>(items: T[]): Array<LaidOutEvent<T>> {
  const sorted = [...items].sort((a, b) => a.start - b.start || a.end - b.end);
  const result: Array<LaidOutEvent<T>> = [];

  let cluster: T[] = [];
  let clusterEnd = -1;

  const flush = () => {
    if (cluster.length === 0) return;
    const laneEnds: number[] = [];
    const placed = cluster.map((event) => {
      let lane = laneEnds.findIndex((end) => end <= event.start);
      if (lane === -1) {
        lane = laneEnds.length;
        laneEnds.push(event.end);
      } else {
        laneEnds[lane] = event.end;
      }
      return { event, lane };
    });
    for (const entry of placed) result.push({ ...entry, lanes: laneEnds.length });
    cluster = [];
    clusterEnd = -1;
  };

  for (const event of sorted) {
    if (cluster.length > 0 && event.start >= clusterEnd) flush();
    cluster.push(event);
    clusterEnd = Math.max(clusterEnd, event.end);
  }
  flush();

  return result;
}

/** Groepeert events per resource, in de volgorde van de resources zelf. */
export function groupByResource<T extends { resource: string }>(
  events: T[],
  resources: Array<{ key: string }>
): Map<string, T[]> {
  const map = new Map<string, T[]>();
  for (const resource of resources) map.set(resource.key, []);
  for (const event of events) {
    const list = map.get(event.resource);
    if (list) list.push(event);
  }
  for (const list of map.values()) {
    list.sort((a, b) => ((a as { start?: number }).start ?? 0) - ((b as { start?: number }).start ?? 0));
  }
  return map;
}

/** Groepeert events per starttijd, oplopend — de basis voor een tijdlijn. */
export function groupByStart<T extends { start: number }>(events: T[]): Array<{ start: number; events: T[] }> {
  const map = new Map<number, T[]>();
  for (const event of events) {
    const list = map.get(event.start) ?? [];
    list.push(event);
    map.set(event.start, list);
  }
  return [...map.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([start, list]) => ({ start, events: list }));
}

/** Telt de items die echt een afspraak zijn (geblokkeerde tijd niet meegerekend). */
export function countBookable(events: Array<{ blocked?: boolean }>): number {
  return events.filter((event) => !event.blocked).length;
}

/** De kleur van een event: eigen kleur, anders die van de resource, anders de toon. */
export function eventColor(
  event: { color?: string; tone?: ScheduleTone },
  resource?: { color?: string }
): string | undefined {
  return event.color ?? resource?.color;
}

/** Huidige tijd in minuten sinds middernacht. */
export function nowMinutes(): number {
  const date = new Date();
  return date.getHours() * 60 + date.getMinutes();
}

/**
 * Datumhulpfuncties — eigen implementatie op basis van de ingebouwde Date en
 * Intl. Geen date-fns, geen dayjs, geen luxon.
 *
 * Alle functies werken met lokale tijd en laten de meegegeven Date ongemoeid.
 */

export interface DateRange {
  from?: Date;
  to?: Date;
}

/** Standaardtaal van het Dafke UI-design. */
export const DEFAULT_LOCALE = "nl-BE";

/* ------------------------------------------------------------------ */
/* Basis                                                               */
/* ------------------------------------------------------------------ */

export function startOfDay(date: Date): Date {
  const copy = new Date(date);
  copy.setHours(0, 0, 0, 0);
  return copy;
}

export function addDays(date: Date, amount: number): Date {
  const copy = new Date(date);
  copy.setDate(copy.getDate() + amount);
  return copy;
}

export function addMonths(date: Date, amount: number): Date {
  const copy = new Date(date);
  const day = copy.getDate();
  copy.setDate(1);
  copy.setMonth(copy.getMonth() + amount);
  copy.setDate(Math.min(day, daysInMonth(copy)));
  return copy;
}

export function daysInMonth(date: Date): number {
  return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
}

export function startOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), 1);
}

export function endOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth() + 1, 0, 23, 59, 59, 999);
}

/** weekStartsOn: 0 = zondag, 1 = maandag (standaard in België). */
export function startOfWeek(date: Date, weekStartsOn = 1): Date {
  const copy = startOfDay(date);
  const diff = (copy.getDay() - weekStartsOn + 7) % 7;
  return addDays(copy, -diff);
}

export function endOfWeek(date: Date, weekStartsOn = 1): Date {
  return addDays(startOfWeek(date, weekStartsOn), 6);
}

/* ------------------------------------------------------------------ */
/* Vergelijken                                                         */
/* ------------------------------------------------------------------ */

export function isSameDay(a?: Date | null, b?: Date | null): boolean {
  if (!a || !b) return false;
  return (
    a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
  );
}

export function isSameMonth(a?: Date | null, b?: Date | null): boolean {
  if (!a || !b) return false;
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
}

export function isToday(date: Date): boolean {
  return isSameDay(date, new Date());
}

export function isWeekend(date: Date): boolean {
  const day = date.getDay();
  return day === 0 || day === 6;
}

export function isBeforeDay(a: Date, b: Date): boolean {
  return startOfDay(a).getTime() < startOfDay(b).getTime();
}

export function isAfterDay(a: Date, b: Date): boolean {
  return startOfDay(a).getTime() > startOfDay(b).getTime();
}

export function isWithin(date: Date, from?: Date | null, to?: Date | null): boolean {
  if (!from || !to) return false;
  const time = startOfDay(date).getTime();
  const start = startOfDay(from).getTime();
  const end = startOfDay(to).getTime();
  return time >= Math.min(start, end) && time <= Math.max(start, end);
}

export function clampDate(date: Date, min?: Date | null, max?: Date | null): Date {
  if (min && isBeforeDay(date, min)) return new Date(min);
  if (max && isAfterDay(date, max)) return new Date(max);
  return date;
}

/** Aantal hele dagen tussen twee datums (b - a). */
export function differenceInDays(a: Date, b: Date): number {
  const millis = startOfDay(b).getTime() - startOfDay(a).getTime();
  return Math.round(millis / 86_400_000);
}

/* ------------------------------------------------------------------ */
/* Weeknummer (ISO 8601)                                               */
/* ------------------------------------------------------------------ */

export function getISOWeek(date: Date): number {
  const target = startOfDay(date);
  // Donderdag van deze week bepaalt het jaar.
  target.setDate(target.getDate() + 3 - ((target.getDay() + 6) % 7));
  const firstThursday = new Date(target.getFullYear(), 0, 4);
  firstThursday.setDate(firstThursday.getDate() + 3 - ((firstThursday.getDay() + 6) % 7));
  return 1 + Math.round((target.getTime() - firstThursday.getTime()) / (7 * 86_400_000));
}

/* ------------------------------------------------------------------ */
/* Rasters                                                             */
/* ------------------------------------------------------------------ */

/** Alle dagen van de maand, aangevuld tot volledige weken (6 × 7 = 42 dagen). */
export function getMonthGrid(month: Date, weekStartsOn = 1): Date[] {
  const first = startOfWeek(startOfMonth(month), weekStartsOn);
  return Array.from({ length: 42 }, (_, index) => addDays(first, index));
}

/** De zeven (of minder) dagen van een week vanaf een datum. */
export function getWeekDays(date: Date, weekStartsOn = 1, length = 7): Date[] {
  const first = startOfWeek(date, weekStartsOn);
  return Array.from({ length }, (_, index) => addDays(first, index));
}

/* ------------------------------------------------------------------ */
/* Formatteren                                                         */
/* ------------------------------------------------------------------ */

const formatterCache = new Map<string, Intl.DateTimeFormat>();

function formatter(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let cached = formatterCache.get(key);
  if (!cached) {
    cached = new Intl.DateTimeFormat(locale, options);
    formatterCache.set(key, cached);
  }
  return cached;
}

export function formatDate(
  date: Date,
  options: Intl.DateTimeFormatOptions = { day: "2-digit", month: "short", year: "numeric" },
  locale: string = DEFAULT_LOCALE
): string {
  return formatter(locale, options).format(date);
}

/** "16 – 20 mrt 2026" of "28 feb – 3 mrt 2026" bij een maandgrens. */
export function formatDateRange(range: DateRange, locale: string = DEFAULT_LOCALE): string {
  if (!range.from) return "";
  if (!range.to || isSameDay(range.from, range.to)) return formatDate(range.from, undefined, locale);

  const sameMonth = isSameMonth(range.from, range.to);
  const sameYear = range.from.getFullYear() === range.to.getFullYear();

  const left = formatDate(
    range.from,
    sameMonth
      ? { day: "numeric" }
      : sameYear
        ? { day: "numeric", month: "short" }
        : { day: "numeric", month: "short", year: "numeric" },
    locale
  );
  const right = formatDate(range.to, { day: "numeric", month: "short", year: "numeric" }, locale);
  return `${left} – ${right}`;
}

/** Namen van de weekdagen, beginnend bij weekStartsOn. */
export function weekdayNames(
  weekStartsOn = 1,
  format: "narrow" | "short" | "long" = "short",
  locale: string = DEFAULT_LOCALE
): string[] {
  const base = new Date(2024, 0, 7); // een zondag
  return Array.from({ length: 7 }, (_, index) =>
    formatter(locale, { weekday: format }).format(addDays(base, (index + weekStartsOn) % 7))
  );
}

export function monthName(month: Date, locale: string = DEFAULT_LOCALE): string {
  return formatDate(month, { month: "long", year: "numeric" }, locale);
}

/* ------------------------------------------------------------------ */
/* Tijd (minuten sinds middernacht)                                     */
/* ------------------------------------------------------------------ */

/** "9:30", "930", "9.30" of "0930" → 570. Geeft null bij onleesbare invoer. */
export function parseTime(input: string): number | null {
  const clean = input.trim().replace(/[.,]/g, ":");
  if (!clean) return null;

  const withSeparator = clean.match(/^(\d{1,2}):(\d{1,2})$/);
  if (withSeparator) {
    return toMinutes(Number(withSeparator[1]), Number(withSeparator[2]));
  }

  const digits = clean.replace(/\D/g, "");
  if (!digits) return null;
  if (digits.length <= 2) return toMinutes(Number(digits), 0);
  if (digits.length === 3) return toMinutes(Number(digits.slice(0, 1)), Number(digits.slice(1)));
  return toMinutes(Number(digits.slice(0, 2)), Number(digits.slice(2, 4)));
}

function toMinutes(hours: number, minutes: number): number | null {
  if (!Number.isFinite(hours) || !Number.isFinite(minutes)) return null;
  if (hours > 23 || minutes > 59) return null;
  return hours * 60 + minutes;
}

/** 570 → "09:30". */
export function formatTime(minutes: number): string {
  const total = ((Math.round(minutes) % 1440) + 1440) % 1440;
  const hours = Math.floor(total / 60);
  const rest = total % 60;
  return `${String(hours).padStart(2, "0")}:${String(rest).padStart(2, "0")}`;
}

/** Rondt af op een veelvoud van `step` minuten. */
export function roundToStep(minutes: number, step: number): number {
  if (step <= 0) return minutes;
  return Math.round(minutes / step) * step;
}

/** Alle tijdstippen tussen from en to, met stappen van `step` minuten. */
export function timeSlots(from: number, to: number, step: number): number[] {
  const slots: number[] = [];
  for (let minutes = from; minutes <= to; minutes += step) slots.push(minutes);
  return slots;
}

/** "2 u 30" — leesbare duur voor diensten en verlof. */
export function formatDuration(minutes: number): string {
  const hours = Math.floor(minutes / 60);
  const rest = Math.round(minutes % 60);
  if (hours === 0) return `${rest} min`;
  if (rest === 0) return `${hours} u`;
  return `${hours} u ${rest}`;
}
